// === Tab: mySketch ===
// by SamuelYAN
// more works //
   // https://twitter.com/SamuelAnn0924
   // https://www.instagram.com/samuel_yan_1990/

let mySize;
let seed = Math.random() * 2000;
//let noff = 1;
let tile_Count = 10;
let cubes = [];

// colors
let colors2 = "ffbe00-ffd675-000000"
  .split("-")
  .map((a) => "#" + a);
// color #RRGGBBAA
let colors1 = "ffbe00e6-ffd675cc-000000e6"
  .split("-")
  .map((a) => "#" + a);

function setup() {
  pixelDensity(5);
  mySize = max(windowWidth, windowHeight);
  createCanvas(mySize, mySize);
  randomSeed(seed);
  noiseSeed(seed);
  background(0);
	let filter = new makeFilter();

  let w = width / tile_Count;

  for (let i = 0; i < tile_Count; i++) {
    for (let j = 0; j < tile_Count; j++) {
      let scaleX = random(0.1, 2);
      let scaleY = random(0.1, 4);
      let x = i * w;
      let y = j * w;
      let ShapeItem = int(random(1));
      if (ShapeItem == 0) {
        cubes.push(
          new makeCubes(
            x + 20 * sin(scaleX),
            y + 20 * cos(scaleY),
            w * scaleX,
            w * scaleY
          )
        );
      }
    }
  }
}

function draw() {
  randomSeed(seed);
  noiseSeed(seed);
  background(0);
  for (let c of cubes) {
    c.display();
  }
	image(overAllTexture, 0, 0);
}

function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(width, height);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					0,
					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

class makeCubes {
  constructor(x, y, wx, wy) {
    this.x = x;
    this.y = y;
    this.wx = wx;
    this.wy = wy;
    this.plus = random(10, 20);
    this.plusX = this.plus;
    this.plusY = this.plus;
    this.col1 = random(colors1);
    this.col2 = random(colors2);
    this.xscale = random(0.5, 1);
    this.yscale = random(0.25, 0.75);
  }

  display() {
    fill(this.col1);
    //noFill();
    stroke(this.col2);
    push();
    translate(
      this.x + (this.wx * this.xscale) / 2,
      this.y + (this.wy * this.yscale) / 2
    );
    rectMode(CENTER);
    rect(0, 0, this.wx * this.xscale, this.wy * this.yscale);
    pop();

    noFill();
    stroke(this.col2);
    push();
    translate(
      this.x + (this.wx * this.xscale) / 2,
      this.y + (this.wy * this.yscale) / 2
    );
    line(
      (-this.wx * this.xscale) / 2,
      (-this.wy * this.yscale) / 2,
      (-this.wx * this.xscale) / 2 + this.plusX,
      (-this.wy * this.yscale) / 2 + this.plusY
    );
    line(
      (-this.wx * this.xscale) / 2,
      (this.wy * this.yscale) / 2,
      (-this.wx * this.xscale) / 2 + this.plusX,
      (this.wy * this.yscale) / 2 + this.plusY
    );
    line(
      (this.wx * this.xscale) / 2,
      (-this.wy * this.yscale) / 2,
      (this.wx * this.xscale) / 2 + this.plusX,
      (-this.wy * this.yscale) / 2 + this.plusY
    );
    line(
      (this.wx * this.xscale) / 2,
      (this.wy * this.yscale) / 2,
      (this.wx * this.xscale) / 2 + this.plusX,
      (this.wy * this.yscale) / 2 + this.plusY
    );
    pop();

    noFill();
    stroke(this.col2);
    //fill(this.col1);
    push();
    translate(
      this.x + (this.wx * this.xscale) / 2 + this.plusX,
      this.y + (this.wy * this.yscale) / 2 + this.plusY
    );
    rectMode(CENTER);
    for (let i = 0; i < 4; i++) {
      rect(
        0,
        0,
        (this.wx - i * 10) * this.xscale,
        (this.wy - i * 10) * this.yscale
      );
    }
    pop();
  }
}

function keyTyped() {
  if (key === "s" || key === "S") {
    saveCanvas("NewCubes-001", "png");
  }
}

